171			 $\G$ group-tests $\tau: \G \to U(\C^{d^n}) $ in the sense of Definition \ref{definition:group-test}.
172			 \item \label{assumption:pauli-in-image-appendix}The image of $\tau$ contains an isomorphic copy of the Pauli group $\m P_d^{\otimes n}$.
173		\end{enumerate}	
