 78	The following is the main tool we use to understand linear constraint system games.
 79	
 80	\begin{definition}[Solution group over $\Z_d$, \cite{cleve2016perfect}]
 81		For an LCS game $\LCS(\mathbf H, l, \Z_d)$ with $\mathbf H = (V,E,H)$, the \emph{solution group} $\G(\mathbf H, l, \Z_d)$ has one generator for each edge of $\mathbf H$ (i.e.\ for each variable of the linear system), one relation for each vertex of $\mathbf H$ (i.e.\ for each equation of the linear system), and relations enforcing that the variables in each equation commute. Formally, define the sets of relations $R_c$, the local commutativity relations, and $R_{eq}$, the constraint satisfaction relations as
 82		\begin{align}
 83			R_{c} 		&:= \set{[e,e'] \; H(v,e) \neq 0 \neq H(v,e')\text{ for some } v\in V}
 84			\\R_{eq}	&:= \set{ J^{-l(v)}\prod_{e\in E}e^{H(v,e)} \; v\in V}.
 85		\end{align}
 86	Then define the solution group as
 87	\begin{equation}
 88		\G(\mathbf H, l, \Z_d) := \Braket{E:R_{c}\cup R_{eq}}_{\Z_d}.
 89	\end{equation}
 90	(Notice that the order of the products defining $R_{eq}$ is irrelevant, since each pair of variables appearing in the same $R_{eq}$ relation also have a commutation relation in $R_c$.)
 91	\end{definition}
 92	When the LCS game is clear from context, we'll just write $\G$ to denote its solution group. 
 93	
 94	
 95	Our aim is to prove that for some specific linear constraint system games, strategies that win with high probability are very close to some ideal form.
 96	We start by observing that for any LCS game, \emph{any} strategy already has a slightly special form.
 97	
 98	\begin{lemma}[Strategies presented via observables]\label{lemma:unitary-observable-strategy-exact}
 99		Suppose that $p(a,b\|v,e) =\Tr_\rho \tilde A_v^a\otimes \tilde B_e^b$ is a quantum strategy for an LCS game over $\Z_d$ with hypergraph $\mathbf H = (H,V,E)$. Then there are unitaries $\set{A_e^{(v)} \; e\in E, v\in V}$ and $\set{B_e \; e\in E}$ such that for all $v,e$, $(A_e^{(v)})^d = I = B_e^d$; for any fixed $v$, the $A_e^{(v)}$ pairwise commute; moreover, the provers win with probability $1$ iff 
100		\begin{equation}\label{eq:exact-win-criterion-con}
101			\text{for all $v,e$, }\Tr_\rho A_e^{(v)}\otimes B_e  = 1\text{, and}
102		\end{equation}
103		\begin{equation}\label{eq:exact-win-criterion-sat}
104			\text{for all }v\text{, }\Tr_\rho \prod_{e}\left(A_e^{(v)}\right)^{H(v,e)}\otimes I_B = \w_d^{l(v)}.
105		\end{equation}
106	\end{lemma}
107	
108	We refer to the operators $\set{A_e^{(v)}}, \set{B_e}$ together with the state $\rho$ as a \emph{strategy presented via observables.}
109	Typically the word ``observable'' is reserved for Hermitian operators. Nonetheless, we call our operators observables because they capture properties of the projective measurements from which they're built in a useful way. Operationally, we think of Bob as measuring the observable $B_e$ and reporting the outcome when asked about variable $e$ and of Alice measuring the observables $A_e^{(v)}$ and reporting the outcome for each $e$ when asked about equation $v$. The fact that Alice's observables pairwise commute at each equation means that Alice can measure them simultaneously without ambiguity.
110	
111	A version of this lemma is proved in the course of the proof of Theorem 1 of \cite{cleve2014characterization}. We give essentially the same proof, just over $\Z_d$.
112	\begin{proof}[Proof of Lemma \ref{lemma:unitary-observable-strategy-exact}]
113		Define the observables as
114		\begin{align}
115			B_e:= \sum_j\w_d^{-j}\tilde B^{i}_{e}
116			&& 
117			A_e^{(v)}:= \sum_i \w_d^i\sum_{a: a(e) =i} \tilde A_{v}^a.
118		\end{align}
119	
120		It's clear that each of these operators is a unitary whose eigenvalues are $d\th$ roots of unity. To see that $A_e^{(v)}$ commutes with $A_{e'}^{(v)}$, notice that they are different linear combinations of the same set of projectors. Now we compute, for any $v,e$,
121		\begin{align}
122			\Tr_\rho A_e^{(v)}\otimes B_e 
123				&= \sum_{i,j}\w_d^{i-j}\Tr_\rho \left(\sum_{a: a(e) =i} \tilde A_{v}^a\right)\otimes \tilde B^{j}_{e} 
124			\\	&= \sum_k \w_d^k\Pr[a(e) - b \equiv k\mid \text{questions } x=v, y=e].
125		\end{align}
126		Notice that the last line is a convex combination of the $d\th$ roots of unity. Hence, it equals $1$ if and only if $\Pr[a(e) \equiv b \mid \text{questions } x=v, y=e] = 1$.
127	
128		A similar computation reveals:
129		\begin{align}
130			 &\w_d^{-l(v)} \Tr_\rho \prod_{e} \left(A_e^{(v)}\right)^{H(v,e)}\otimes I \\
131			% =& \Braket {\psi |\prod_{e} \left(\sum_i \w_d^i\sum_{a: a(e) =i} \tilde A_{v}^a\right)^{H(v,e)}\otimes I | \psi } \\
132			% \\=& \Braket {\psi |\prod_{e} \left(\sum_i \w_d^{iH(v,e)}\sum_{a: a(e) =i} \tilde A_{v}^a\right)\otimes I | \psi} \\
133			= & \sum_k\w_d^{k-l(v)} \Tr_\rho \sum_{\substack{a\\ \sum_e H(v,e)a(e)\equiv k}} \tilde A_{v}^a\otimes I \\
134			= & \sum_k \w_d^{k-l(v)}\Pr\left[\sum_{e}H(v,e)a(e)\equiv k\middle|  \text{question } x=v\right]
135		\end{align}
136	Again, the last line is a convex combination of the $d\th$ roots of unity. Hence it equals $1$ if and only if $\Pr\left[\sum_{e}H(v,e)a(e)\equiv l(v) \middle|  \text{question } x=v\right] = 1$. 
137	\end{proof}
